from flask import Flask, render_template
import pandas as pd

app = Flask(__name__)

@app.route("/")
def index():
    # Load the customer profiles generated by your ML script
    df = pd.read_csv("customer_profiles.csv")
    # Convert to list of dicts for easy rendering
    profiles = df.to_dict(orient="records")
    return render_template("index.html", profiles=profiles)

if __name__ == "__main__":
    app.run(debug=True)
